#!/usr/bin/env bash
# Installs/updates the aivoicebus mesh on its three nodes. DRY RUN by default.
#
#   ./deploy/install.sh                  # print the plan, touch nothing
#   ./deploy/install.sh --apply          # install on every reachable node, one at a time
#   ./deploy/install.sh --apply node-a     # only that node
#
# Needs: network access (nodes must reach each other and you must reach them on tcp:7777),
# and the shared token at
# ~/.config/aivoicebus/token (generated by --gen-token; never printed).
#
# The binary: set AIVOICEBUS_BIN to a prebuilt linux/amd64 aivoicebus (the one from the
# signed release, so the nodes run exactly what was released). Without it the script
# builds one on THIS machine, which belongs on a build host, not a laptop.
# Each node keeps its previous binary as /usr/local/bin/aivoicebus.prev; to roll back:
#   ssh <node> 'install -m 755 /usr/local/bin/aivoicebus.prev /usr/local/bin/aivoicebus && systemctl restart aivoicebus'
# (install, not cp: it replaces the file, so a running binary does not fail with "Text file busy"; or use deploy/rollout.sh, which rolls back by itself)
# Observers (a dashboard or exporter): if ~/.config/aivoicebus/observer-token exists (make it with
# --gen-observer-token), every node also accepts that second, READ-ONLY token (replication
# feed, roster, threads; it cannot send, ack, read an inbox or fetch a release). Without the
# file the nodes accept the shared token only, and a previously installed observer token is removed.
# Adding a node: put its line in deploy/nodes.conf, install it (--apply <node>), then refresh the
# others' peer lists WITHOUT touching their binary or rollback copy: --apply --peers-only.
# A re-install of the same binary no longer overwrites aivoicebus.prev (only a changed binary does).
# A temporary BOOTSTRAP_ARGS line in node.env (deploy/bootstrap-share.sh) is preserved.
# Rotating the shared token: deploy/rotate-token.sh drives --tokens-only, which rewrites the token
# files and restarts each node (one at a time) without touching its binary or unit. If
# ~/.config/aivoicebus/token.nodes exists it is what nodes get as their token file (one or two
# tokens, see rotate-token.sh); otherwise the token file itself.
# A node that cannot be reached is skipped with a message and the script ends with status 3, so a
# caller (rotate-token.sh, machine-token.sh) never mistakes "skipped" for "done".
# Idempotent: re-running upgrades the binary/unit and restarts one node at a time,
# waiting for /healthz before moving on, so the mesh never loses more than one node.
set -euo pipefail
cd "$(dirname "$0")/.."

PORT="${AIVOICEBUS_PORT:-7777}"   # AIVOICEBUS_PORT: a node port other than 7777 (one already taken on the hosts)
. deploy/nodes.sh   # NODES (name:alias:ip) from deploy/nodes.conf, the one list of nodes
. deploy/ops.sh
TOKEN_FILE="${AIVOICEBUS_TOKEN_FILE:-$HOME/.config/aivoicebus/token}"
OBSERVER_FILE="${AIVOICEBUS_OBSERVER_TOKEN_FILE:-$HOME/.config/aivoicebus/observer-token}"

NODE_TOKENS_FILE="${AIVOICEBUS_NODE_TOKENS_FILE:-$HOME/.config/aivoicebus/token.nodes}"
[ -s "$NODE_TOKENS_FILE" ] || NODE_TOKENS_FILE="$TOKEN_FILE"   # what nodes get: the rotation payload, else the token
MACHINE_DIR="${AIVOICEBUS_MACHINE_TOKENS_DIR:-$HOME/.config/aivoicebus/machine-tokens}"
STAGE=/etc/aivoicebus/stage   # root-only: files are staged here, never in /tmp

# node_tokens prints the whole token file a node gets: the shared token(s), then one
# "host:token" line per machine token (deploy/machine-token.sh), each bound to that machine.
# A file that is not a valid machine token stops everything: a node refuses a token file it
# cannot parse, and would then not start.
node_tokens() {
  cat "$NODE_TOKENS_FILE"; echo
  local f name tok
  for f in "$MACHINE_DIR"/*; do
    [ -e "$f" ] || continue
    name=$(basename "$f"); tok=$(tr -d '\n' <"$f" 2>/dev/null || true)
    [ -f "$f" ] && [[ "$name" =~ ^[a-z0-9][a-z0-9._-]{0,62}$ ]] || { echo "$MACHINE_DIR/$name is not a machine token file (a file named for the host)" >&2; return 1; }
    [ "${#tok}" -ge 24 ] || { echo "the machine token for $name is shorter than 24 characters" >&2; return 1; }
    printf '%s:%s\n' "$name" "$tok"
  done
}

# check_tokens: the file nodes would get parses (every token 24+ characters, none twice). The
# classic mistake it catches: this machine's own token, a machine token, sitting in
# ~/.config/aivoicebus/token, which would be pushed to every node as the shared token.
check_tokens() {
  local all line tok seen=$'\n'
  all=$(node_tokens) || return 1
  while IFS= read -r line; do
    [ -n "$line" ] || continue
    tok="${line##*:}"
    [ "${#tok}" -ge 24 ] || { echo "a token in the node token file is shorter than 24 characters" >&2; return 1; }
    case "$seen" in
      *$'\n'"$tok"$'\n'*) echo "the same token appears twice in what nodes would get. Is $TOKEN_FILE a machine token (one of $MACHINE_DIR)? It must be the shared token." >&2; return 1 ;;
    esac
    seen="$seen$tok"$'\n'
  done <<<"$all"
  return 0
}

APPLY=0; ONLY=""; PEERS_ONLY=0; TOKENS_ONLY=0
for a in "$@"; do
  case "$a" in
    --apply) APPLY=1 ;;
    --peers-only) PEERS_ONLY=1 ;;
    --tokens-only) PEERS_ONLY=1; TOKENS_ONLY=1 ;;
    --gen-token)
      [ -e "$TOKEN_FILE" ] && { echo "token already exists at $TOKEN_FILE; not overwriting"; exit 0; }
      mkdir -p "$(dirname "$TOKEN_FILE")"; gen_token "$TOKEN_FILE"
      echo "token written to $TOKEN_FILE (mode 600, not printed)"; exit 0 ;;
    --gen-observer-token)
      [ -e "$OBSERVER_FILE" ] && { echo "observer token already exists at $OBSERVER_FILE; not overwriting"; exit 0; }
      mkdir -p "$(dirname "$OBSERVER_FILE")"; gen_token "$OBSERVER_FILE"
      echo "observer token written to $OBSERVER_FILE (mode 600, not printed)"; exit 0 ;;
    -*) echo "usage: $0 [--gen-token] [--gen-observer-token] [--apply] [--peers-only | --tokens-only] [node]" >&2; exit 2 ;;
    *) ONLY="$a" ;;
  esac
done
[ -s "$TOKEN_FILE" ] || { echo "no token at $TOKEN_FILE; run: $0 --gen-token" >&2; exit 1; }
[ "$(wc -c < "$TOKEN_FILE")" -ge 24 ] || { echo "token shorter than 24 chars" >&2; exit 1; }
check_tokens

OBS=0
if [ -s "$OBSERVER_FILE" ]; then
  [ "$(wc -c < "$OBSERVER_FILE")" -ge 24 ] || { echo "observer token shorter than 24 chars" >&2; exit 1; }
  cmp -s "$OBSERVER_FILE" "$TOKEN_FILE" && { echo "the observer token must differ from the shared token" >&2; exit 1; }
  OBS=1
fi

peers_for() { # all nodes except $1
  local out="" n
  for n in "${NODES[@]}"; do IFS=: read -r name _ ip <<<"$n"
    [ "$name" = "$1" ] || out="$out,http://$ip:$PORT"
  done; echo "${out#,}"
}

BIN=""
if [ "$TOKENS_ONLY" = 1 ]; then
  echo "tokens-only: token files and the service are refreshed; binary, unit, observer setup and rollback copy are left alone"
elif [ "$PEERS_ONLY" = 1 ]; then
  echo "peers-only: node.env and the service are refreshed; binary, unit, observer setup and rollback copy are left alone"
elif [ -n "${AIVOICEBUS_BIN:-}" ]; then
  BIN="$AIVOICEBUS_BIN"
  [ -x "$BIN" ] || { echo "AIVOICEBUS_BIN=$BIN is not an executable file" >&2; exit 1; }
  echo "using the prebuilt binary $BIN"
else
  BIN=$(mktemp -d)/aivoicebus
  trap 'rm -rf "$(dirname "$BIN")"' EXIT
  echo "building linux/amd64 binary on this machine (prefer a build host, then AIVOICEBUS_BIN)..."
  scripts/build.sh linux amd64 "$BIN"
fi
[ -z "$BIN" ] || echo "  sha256 $(shasum -a 256 "$BIN" | cut -c1-16)  size $(wc -c < "$BIN")"

SKIPPED=()
for n in "${NODES[@]}"; do IFS=: read -r name alias ip <<<"$n"
  [ -z "$ONLY" ] || [ "$ONLY" = "$name" ] || continue
  peers=$(peers_for "$name")
  echo; echo "== $name ($alias, $ip:$PORT) peers: $peers"
  if [ "$APPLY" = 0 ]; then
    [ "$TOKENS_ONLY" = 0 ] || echo "   would: write the token file ($(node_tokens | grep -c .) token(s)) to /etc/aivoicebus/token (600)"
    [ "$PEERS_ONLY" = 0 ] || echo "   would: rewrite node.env with these peers and restart the service (binary and rollback copy untouched)"
    [ "$PEERS_ONLY" = 1 ] && continue
    echo "   would: copy binary -> /usr/local/bin/aivoicebus (old one kept as aivoicebus.prev when it differs), unit -> /etc/systemd/system/aivoicebus.service,"
    echo "          token -> /etc/aivoicebus/token (600), node.env (NODE=$name ADDR=$ip:$PORT), enable --now, wait /healthz"
    [ "$OBS" = 0 ] || echo "          observer token -> /etc/aivoicebus/observer-token (600, read-only feed for the dashboard)"
    continue
  fi
  if ! ssh_ok "$alias"; then
    echo "   UNREACHABLE, skipping (re-run later with: $0 --apply $name)"; SKIPPED+=("$name"); continue
  fi
  # Never overwrite a running node's token file with a token the node does not accept as the
  # shared one: that is how a machine's own token, or a stale file on another admin's laptop,
  # would take every other machine's access away.
  if { [ "$PEERS_ONLY" = 0 ] || [ "$TOKENS_ONLY" = 1 ]; } && [ -z "${AIVOICEBUS_FORCE_TOKEN:-}" ]; then
    trusted=0; answered=0
    for probe in "$TOKEN_FILE" "$TOKEN_FILE.next"; do # the staged next token counts: a rotation may be half done
      [ -s "$probe" ] || continue
      rc=0; is_shared_token "$probe" "$ip" || rc=$?
      [ "$rc" = 2 ] && trusted=1                           # an older node cannot say
      [ "$rc" = 0 ] && trusted=1
      [ "$(http_code "$probe" "http://$ip:$PORT/v1/who")" = 000 ] || answered=1
    done
    if [ "$trusted" = 0 ] && [ "$answered" = 1 ]; then
      echo "   $name does not accept $TOKEN_FILE as the shared token (or it is a machine token). Refusing to overwrite its token file. AIVOICEBUS_FORCE_TOKEN=1 overrides, for a node whose token you are deliberately replacing." >&2; exit 1
    fi
  fi

  TOKSTEP=':'; TOKFAIL=':'
  if [ "$PEERS_ONLY" = 0 ] || [ "$TOKENS_ONLY" = 1 ]; then
    # the new token file is staged, then moved into place just before the restart; if the node
    # does not come back the old file is put back
    node_tokens | ssh "$alias" "install -d -m 700 /etc/aivoicebus $STAGE && umask 077 && cat > /etc/aivoicebus/token.new"
    TOKSTEP='cp -p /etc/aivoicebus/token /etc/aivoicebus/token.prev 2>/dev/null || true; mv /etc/aivoicebus/token.new /etc/aivoicebus/token'
    TOKFAIL='if [ -e /etc/aivoicebus/token.prev ]; then cp -p /etc/aivoicebus/token.prev /etc/aivoicebus/token; systemctl restart aivoicebus; echo "   previous token file restored"; fi'
  fi
  BINSTEP=':'
  if [ "$PEERS_ONLY" = 0 ]; then
    ssh -n "$alias" "install -d -m 700 /etc/aivoicebus $STAGE"
    scp -q "$BIN" "$alias:$STAGE/aivoicebus.new"
    scp -q deploy/aivoicebus.service "$alias:$STAGE/aivoicebus.service.new"
    [ "$OBS" = 0 ] || ssh "$alias" 'umask 077 && cat > /etc/aivoicebus/observer-token' < "$OBSERVER_FILE"
    BINSTEP="if ! cmp -s $STAGE/aivoicebus.new /usr/local/bin/aivoicebus 2>/dev/null; then
      [ ! -e /usr/local/bin/aivoicebus ] || cp -p /usr/local/bin/aivoicebus /usr/local/bin/aivoicebus.prev
      [ ! -e /etc/systemd/system/aivoicebus.service ] || cp -p /etc/systemd/system/aivoicebus.service /etc/systemd/system/aivoicebus.service.prev
    fi
    install -m 755 $STAGE/aivoicebus.new /usr/local/bin/aivoicebus
    install -m 644 $STAGE/aivoicebus.service.new /etc/systemd/system/aivoicebus.service
    rm -f $STAGE/aivoicebus.new $STAGE/aivoicebus.service.new"
  fi
  ssh -n "$alias" "set -e
    install -d -m 755 /srv/aivoicebus-release
    keep=\$(grep '^BOOTSTRAP_ARGS=' /etc/aivoicebus/node.env 2>/dev/null || true)
    keepobs=\$(grep '^OBSERVER_ARGS=' /etc/aivoicebus/node.env 2>/dev/null || true)
    printf 'NODE=%s\nADDR=%s\nPEERS=%s\nRELEASE_ARGS=--release-dir /srv/aivoicebus-release\n' '$name' '$ip:$PORT' '$peers' > /etc/aivoicebus/node.env
    [ -z \"\$keep\" ] || echo \"\$keep\" >> /etc/aivoicebus/node.env
    if [ '$PEERS_ONLY' = 1 ]; then
      [ -z \"\$keepobs\" ] || echo \"\$keepobs\" >> /etc/aivoicebus/node.env   # the observer setup stays as the node has it
    elif [ '$OBS' = 1 ]; then
      install -d -m 755 /etc/systemd/system/aivoicebus.service.d
      printf '[Service]\nLoadCredential=observer:/etc/aivoicebus/observer-token\n' > /etc/systemd/system/aivoicebus.service.d/observer.conf
      echo 'OBSERVER_ARGS=--observer-token-file /run/credentials/aivoicebus.service/observer' >> /etc/aivoicebus/node.env
    else
      rm -f /etc/systemd/system/aivoicebus.service.d/observer.conf /etc/aivoicebus/observer-token
    fi
    chmod 600 /etc/aivoicebus/node.env
    $BINSTEP
    $TOKSTEP
    systemctl daemon-reload
    systemctl enable aivoicebus >/dev/null 2>&1
    systemctl restart aivoicebus
    for i in \$(seq 1 ${AIVOICEBUS_HEALTH_WAIT:-40}); do curl -fsS http://$ip:$PORT/healthz >/dev/null 2>&1 && { echo '   healthy'; /usr/local/bin/aivoicebus version 2>&1 | sed 's/^/   /'; exit 0; }; sleep 1; done
    echo '   NOT healthy; last log lines:'; journalctl -u aivoicebus -n 15 --no-pager
    $TOKFAIL
    exit 1"
done
echo
if [ "${#SKIPPED[@]}" -gt 0 ]; then
  echo "NOT DONE: skipped unreachable node(s): ${SKIPPED[*]}. Re-run when they are back." >&2
  exit 3
fi
[ "$APPLY" = 1 ] && echo "done. Check: AIVOICEBUS_URL=$(node_urls) aivoicebus who" || echo "dry run only."
